        return {str(key): science_value(item) for key, item in value.items() if str(key) not in REMOVED}
    if isinstance(value, list):
        return [science_value(item) for item in value]
    return value

CGROUP_DIAGNOSTIC_SCHEMA = "mft-tier1-cgroup-memory-diagnostics-v2"
CGROUP_SNAPSHOT_SCHEMA = "mft-tier1-cgroup-memory-snapshot-v2"
CGROUP_DIAGNOSTIC_MAX_BYTES = 262144
